const fs = require("fs");
const path = require("path");

const FAKE_HTML_TEMPLATE = fs.readFileSync(
  path.join(__dirname, "../data/fakePage.html"),
  "utf8"
);

function solveTurnstileMin({ url, proxy, siteKey }) {
  return new Promise(async (resolve, reject) => {
    if (!url) return reject(new Error("Missing url parameter"));
    if (!siteKey) return reject(new Error("Missing siteKey parameter"));

    const context = await global.browser
      .createBrowserContext({
        proxyServer: proxy ? `http://${proxy.host}:${proxy.port}` : undefined,
      })
      .catch(() => null);
    if (!context) return reject(new Error("Failed to create browser context"));

    let isResolved = false;

    const cl = setTimeout(async () => {
      if (!isResolved) {
        isResolved = true;
        await context.close().catch(() => {});
        reject(new Error("Timeout Error: Turnstile token was not received within timeout"));
      }
    }, global.timeOut || 60000);

    try {
      const page = await context.newPage();

      if (proxy?.username && proxy?.password) {
        await page.authenticate({
          username: proxy.username,
          password: proxy.password,
        });
      }

      await page.setRequestInterception(true);

      const normalizedTarget = url.replace(/\/$/, "");

      page.on("request", async (request) => {
        const reqUrl = request.url();
        if (
          (reqUrl === normalizedTarget || reqUrl === normalizedTarget + "/") &&
          request.resourceType() === "document"
        ) {
          await request.respond({
            status: 200,
            contentType: "text/html",
            body: FAKE_HTML_TEMPLATE.replace(/<site-key>/g, siteKey),
          });
        } else {
          await request.continue();
        }
      });

      await page.goto(url, {
        waitUntil: "domcontentloaded",
        timeout: 45000,
      });

      await page.waitForSelector('[name="cf-response"]', {
        timeout: global.timeOut || 60000,
      });

      const token = await page.evaluate(() => {
        try {
          return document.querySelector('[name="cf-response"]')?.value || null;
        } catch (e) {
          return null;
        }
      });

      isResolved = true;
      clearTimeout(cl);
      await context.close().catch(() => {});

      if (!token || token.length < 10) return reject(new Error("Failed to get token: Captured token is empty or invalid"));
      return resolve(token);
    } catch (e) {
      if (!isResolved) {
        isResolved = true;
        clearTimeout(cl);
        await context.close().catch(() => {});
        reject(e?.message ? e : new Error(String(e || "Turnstile-min solving failed")));
      }
    }
  });
}

module.exports = solveTurnstileMin;
